{
	jas_matrix_t *matrix;
	int numrows, numcols;
	assert(xstart <= xend && ystart <= yend);
	if (xend - xstart < 0 || yend - ystart < 0) {
		return 0;
	}
	numrows = yend - ystart;
	numcols = xend - xstart;
	if (!(matrix = jas_matrix_create(numrows, numcols))) {
		return 0;
	}
	matrix->xstart_ = xstart;
	matrix->ystart_ = ystart;
	matrix->xend_ = xend;
	matrix->yend_ = yend;
	return matrix;
}

